"""RPG time-to-kill balance sweep.

Damage model: dps = attack * (1 - armor/(armor+100))
              = attack * 100 / (armor + 100)

TTK for a target with `hp` hit points: ttk = hp / dps.
"""

import csv

ATTACKS = [20, 40, 60, 80, 100]
ARMORS = [0, 50, 100, 200, 400]
HP = 1000
OUTFILE = "ttk.csv"


def dps(attack: float, armor: float) -> float:
    """Damage per second against a target with the given armor."""
    return attack * (1 - armor / (armor + 100))


def ttk(hp: float, attack: float, armor: float) -> float:
    """Time to kill a target with `hp` hit points."""
    return hp / dps(attack, armor)


def main() -> None:
    with open(OUTFILE, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["attack", "armor", "dps", "ttk"])
        for a in ATTACKS:
            for ar in ARMORS:
                d = dps(a, ar)
                w.writerow([a, ar, d, HP / d])


if __name__ == "__main__":
    main()

import csv

from ttk import ATTACKS, ARMORS, OUTFILE, dps, ttk


def _rows():
    with open(OUTFILE) as f:
        r = csv.DictReader(f)
        return list(r), r.fieldnames


def test_ttk_strictly_decreasing_in_attack():
    for armor in ARMORS:
        vals = [ttk(1000, a, armor) for a in ATTACKS]
        assert all(x > y for x, y in zip(vals, vals[1:])), (armor, vals)


def test_ttk_strictly_increasing_in_armor():
    for attack in ATTACKS:
        vals = [ttk(1000, attack, ar) for ar in ARMORS]
        assert all(x < y for x, y in zip(vals, vals[1:])), (attack, vals)


def test_no_full_immunity():
    # dps = attack * 100/(armor+100) > 0 for any finite armor, so TTK is always finite.
    for attack in ATTACKS:
        for armor in ARMORS + [10**9]:
            assert dps(attack, armor) > 0
            assert ttk(1000, attack, armor) < float("inf")


def test_diminishing_returns_100_to_200():
    # Ratio bound: TTK(a, A) = (hp/a) * (A+100)/100, so TTK(200)/TTK(100) = 300/200 = 1.5 exactly.
    # Assert the derived exact ratio: doubling armor multiplies TTK by at most 1.5 < 2.
    for attack in ATTACKS:
        r = ttk(1000, attack, 200) / ttk(1000, attack, 100)
        assert abs(r - 1.5) < 1e-12
        assert r < 2.0


def test_csv_has_exactly_26_lines():
    rows, fields = _rows()
    assert fields == ["attack", "armor", "dps", "ttk"]
    assert len(rows) == 25  # header + 5 attacks x 5 armors
    with open(OUTFILE, "rb") as f:
        n_lines = sum(1 for _ in f)
    assert n_lines == 26

